document.querySelector("#batch38 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/paranormal-64.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف أسطورتهم: سلسلة ما وراء الطبيعة 64\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">روايات · مرجع تجاري</span><h3>أسطورتهم: سلسلة ما وراء الطبيعة 64</h3><p>تعود النبذة إلى موضوع التحريك عن بعد، لكنها توسع أسئلتها: هل أصحاب القدرة كيانات بعيدة أم بشر مثلنا؟ وهل الفرق موهبة خفية أم طريقة لاكتشافها؟ تنق…</p><small>أحمد خالد توفيق</small></a><a class=\"card\" href=\"summaries/paranormal-65.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف أسطورة العلامات الدامية : سلسلة ما وراء الطبيعة 65\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">روايات · مرجع تجاري</span><h3>أسطورة العلامات الدامية : سلسلة ما وراء الطبيعة 65</h3><p>المقتطف المنشور ليس عرضا للحبكة، بل تعليق على إعادة كتابة هذا العدد بالكامل بعد نسخته الأولى. يضعنا ذلك أمام أثر المراجعة في العمل الأدبي: الكتاب…</p><small>أحمد خالد توفيق</small></a><a class=\"card\" href=\"summaries/paranormal-66.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف أسطورة الرجال الذين لم يعودوا كذلك : سلسلة ما وراء الطبيعة 66\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">روايات · مرجع تجاري</span><h3>أسطورة الرجال الذين لم يعودوا كذلك : سلسلة ما وراء الطبيعة 66</h3><p>يعرض المقتطف ليلة هادئة تجمع موسيقى شوبرت والشراب الساخن والبخور. يتوقف الوصف عند تداخل الحواس حتى تبدو الموسيقى قابلة للشم والرائحة قابلة للإصغا…</p><small>أحمد خالد توفيق</small></a>");
